[
  {
    "title": "當量點與終點的差異",
    "body": "當量點是反應物依化學計量恰好完全反應的時刻；終點是指示劑顏色改變的觀察時刻。兩者可能有些微差距。",
    "examples": [
      "強酸強鹼滴定中，酚酞變色的終點應盡量接近當量點。"
    ]
  },
  {
    "title": "由反應比例計算濃度",
    "body": "先用滴定液濃度乘體積求其莫耳數，再依反應式的係數比例求待測物莫耳數，最後除以待測溶液體積。",
    "examples": [
      "一元酸與一元鹼反應時，當量點的酸、鹼莫耳數相等。"
    ]
  },
  {
    "title": "半當量點的酸鹼關係",
    "body": "弱酸以強鹼滴定時，半當量點有一半弱酸轉成共軛鹼，因此 pH 等於弱酸的 pKa。",
    "examples": [
      "醋酸滴定達半當量點時，pH 等於醋酸的 pKa。"
    ]
  }
]
